package local.tvmorph.cleanercheck;
import android.app.Instrumentation;import android.app.Activity;import android.os.Bundle;import java.io.*;import org.json.*;import local.tvmorph.tv.CleanerFiles;
public final class AndroidCleanerCheck extends Instrumentation {
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String message)throws Exception{if(!ok)throw new Exception(message);}
 private String id(JSONObject result,File file)throws Exception{JSONArray rows=result.getJSONArray("files");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);if(row.getString("path").equals(file.getCanonicalPath()))return row.getString("id");}throw new Exception("App cache fixture was not found: "+file.getCanonicalPath());}
 public void onStart(){Bundle result=new Bundle();File folder=new File(getTargetContext().getCacheDir(),"cleaner-instrumentation-fixtures"),one=new File(folder,"selected.tmp"),keep=new File(folder,"keep.tmp");try{check(folder.exists()||folder.mkdirs(),"Cannot create fixture directory");try(FileOutputStream out=new FileOutputStream(one)){out.write("temporary fixture".getBytes("UTF-8"));}try(FileOutputStream out=new FileOutputStream(keep)){out.write("keep".getBytes("UTF-8"));}CleanerFiles files=new CleanerFiles(getTargetContext());String old=id(files.scan("cache",null),one);try(FileOutputStream out=new FileOutputStream(one,true)){out.write(1);}JSONObject rejected=files.remove(new JSONArray().put(old).toString());check(rejected.getJSONArray("ids").length()==0&&one.exists(),"Changed file was removed");String selected=id(files.scan("cache",null),one);check(one.exists(),"Scan deleted data");JSONObject deleted=files.remove(new JSONArray().put(selected).put("/sdcard/DCIM").toString());check(deleted.getJSONArray("ids").length()==1&&!one.exists()&&keep.exists(),"Selection deletion was incorrect");result.putString("result","PASS real Android app-cache scan, changed-file guard, explicit opaque ID deletion and preservation of unselected data");finish(Activity.RESULT_OK,result);}catch(Throwable error){result.putString("error",error.toString());finish(Activity.RESULT_CANCELED,result);}finally{one.delete();keep.delete();folder.delete();}}
}
